with ranked as (select *, row_number() over (partition by device_code order by temp_c nulls first, id) as latest_rank from device_readings qualify latest_rank = 1) select case when temp_c >= 34.9 then 'HIGH' else 'LOW' end as temp_c_tier, percentile_approx(temp_c, array(0.25, 0.5, 0.75)) as temp_c_quartiles, count(distinct id) as distinct_ids, sum(case when device_code = 'DV-01' then humidity else 0 end) as dv_01_humidity from ranked group by temp_c_tier having dv_01_humidity >= 0 order by distinct_ids desc nulls last;
